const CASES: &str = include_str!("data/kt5/cases.txt");
const GOLDEN: &str = include_str!("data/kt5/golden.txt");

fn value(spec: &str) -> Option<ConstValue> {
    if spec == "N" {
        return None;
    }
    let v = &spec[2..];
    Some(match &spec[..1] {
        "I" => ConstValue::Int(v.parse().unwrap()),
        "J" => ConstValue::Long(v.parse().unwrap()),
        "F" => ConstValue::Float(f32::from_bits(u32::from_str_radix(v, 16).unwrap())),
        "D" => ConstValue::Double(f64::from_bits(u64::from_str_radix(v, 16).unwrap())),
        "S" => {
            let units: Vec<u16> = (1..v.len())
                .step_by(4)
                .map(|i| u16::from_str_radix(&v[i..i + 4], 16).unwrap())
                .collect();
            ConstValue::String(from_utf16(&units))
        }
        other => panic!("bad value spec {other}"),
    })
}

fn func_type(name: &str) -> FunctionType {
    *FunctionType::VALUES
        .iter()
        .find(|t| t.name() == name)
        .unwrap_or_else(|| panic!("unknown function type {name}"))
}

fn k_func_type(name: &str) -> KFunctionType {
    [
        KFunctionType::None,
        KFunctionType::Equals3,
        KFunctionType::IfNull,
        KFunctionType::GetKclass,
        KFunctionType::StrTemplate,
    ]
    .into_iter()
    .find(|t| t.name() == name)
    .unwrap_or_else(|| panic!("unknown Kotlin function type {name}"))
}

fn k_type(name: &str) -> KType {
    match name {
        "UNIT" => KType::UNIT(),
        "NOTHING" => KType::NOTHING(),
        "UBYTE" => KType::UBYTE(),
        "USHORT" => KType::USHORT(),
        "UINT" => KType::UINT(),
        "ULONG" => KType::ULONG(),
        other => panic!("unknown KType {other}"),
    }
}

fn declaration_type(name: &str) -> Option<DeclarationType> {
    match name {
        "N" => None,
        "DEFINITION" => Some(DeclarationType::Definition),
        "USAGE" => Some(DeclarationType::Usage),
        "FOR_LOOP_VARIABLE" => Some(DeclarationType::ForLoopVariable),
        "EXCEPTION_TYPE" => Some(DeclarationType::ExceptionType),
        other => panic!("unknown declaration type {other}"),
    }
}

fn use_site_target(name: &str) -> Option<UseSiteTarget> {
    Some(match name {
        "-" => return None,
        "FILE" => UseSiteTarget::File,
        "PROPERTY" => UseSiteTarget::Property,
        "FIELD" => UseSiteTarget::Field,
        "GET" => UseSiteTarget::Get,
        "SET" => UseSiteTarget::Set,
        "RECEIVER" => UseSiteTarget::Receiver,
        "PARAM" => UseSiteTarget::Param,
        "SETPARAM" => UseSiteTarget::Setparam,
        "DELEGATE" => UseSiteTarget::Delegate,
        other => panic!("unknown use-site target {other}"),
    })
}

fn descriptor(spec: &str) -> String {
    spec.replace('<', "(").replace('>', ")")
}

/// `KUtils.replaceExprent`, over this slice's constructors.
fn k_wrap(ex: Exprent) -> Option<Exprent> {
    if ex.is_kotlin() {
        return Some(ex);
    }
    Some(if let Some(e) = ex.try_as_function() {
        KFunctionExprent::new(e).into()
    } else if let Some(e) = ex.try_as_var() {
        KVarExprent::new(e).into()
    } else if let Some(e) = ex.try_as_invocation() {
        KInvocationExprent::new(e).into()
    } else if let Some(e) = ex.try_as_const() {
        KConstExprent::new(e).into()
    } else if let Some(e) = ex.try_as_field() {
        KFieldExprent::new(e).into()
    } else if let Some(e) = ex.try_as_annotation() {
        KAnnotationExprent::new(e).into()
    } else if let Some(e) = ex.try_as_switch_head() {
        KSwitchHeadExprent::new(e).into()
    } else if let Some(e) = ex.try_as_new() {
        KNewExprent::new(e).into()
    } else if let Some(e) = ex.try_as_exit() {
        KExitExprent::new(e).into()
    } else {
        return None;
    })
}

struct Parser {
    toks: Vec<String>,
    pos: usize,
}

impl Parser {
    fn build(tree: &str) -> Exprent {
        let spaced = tree.replace('(', " ( ").replace(')', " ) ");
        let mut parser = Parser {
            toks: spaced.split_whitespace().map(str::to_string).collect(),
            pos: 0,
        };
        parser.parse()
    }

    fn next(&mut self) -> String {
        self.pos += 1;
        self.toks[self.pos - 1].clone()
    }

    fn rest(&mut self) -> Vec<Exprent> {
        let mut ops = Vec::new();
        while self.toks[self.pos] != ")" {
            ops.push(self.parse());
        }
        self.pos += 1;
        ops
    }

    fn parse(&mut self) -> Exprent {
        let t = self.next();
        if t == "(" {
            let head = self.next();
            let p: Vec<&str> = head.split(':').collect();
            return match p[0] {
                "=" => {
                    let ops = self.rest();
                    AssignmentExprent::new(ops[0], ops[1], None).0
                }
                "F" | "KF" | "KK" => {
                    let mut spec = head[p[0].len() + 1..].to_string();
                    let mut implicit = None;
                    if let Some(at) = spec.find('@') {
                        implicit = Some(spec[at + 1..].to_string());
                        spec.truncate(at);
                    }
                    let no_cast = spec.ends_with('!');
                    if no_cast {
                        spec.pop();
                    }
                    let ops = self.rest();
                    let f: FunctionExprent = match p[0] {
                        "F" => FunctionExprent::new(func_type(&spec), ops, None),
                        "KF" => KFunctionExprent::new_func_type(func_type(&spec), ops, None).0,
                        _ => KFunctionExprent::new_k_type(k_func_type(&spec), ops, None).0,
                    };
                    if no_cast {
                        f.set_needs_cast(false);
                    }
                    if let Some(implicit) = implicit {
                        f.set_implicit_type(Some(vartype(&implicit)));
                    }
                    f.0
                }
                "KC" => {
                    let ops = self.rest();
                    KFunctionExprent::new(ops[0].as_function()).into()
                }
                "K" => {
                    let ops = self.rest();
                    k_wrap(ops[0]).expect("KUtils.replaceExprent")
                }
                "KV" => {
                    let ops = self.rest();
                    let v = ops[0].as_var();
                    if p.len() > 2 && p[2] == "F" {
                        v.set_effectively_final(true);
                    }
                    let k = k_wrap(v.0).expect("KVarExprent").as_k_var();
                    k.set_declaration_type(declaration_type(p[1]));
                    k.into()
                }
                "I" => {
                    let mut ops = self.rest();
                    let inv = InvocationExprent::new();
                    inv.set_classname(p[1].to_string());
                    inv.set_name(p[2].to_string());
                    let desc = descriptor(p[3]);
                    inv.set_string_descriptor(desc.clone());
                    inv.set_descriptor(MethodDescriptor::parse_descriptor(&desc));
                    let is_static = p[4].contains('s');
                    inv.set_static(is_static);
                    inv.set_functype(if p[4].contains('i') {
                        InvocationKind::Init
                    } else {
                        InvocationKind::General
                    });
                    if !is_static {
                        inv.set_instance(Some(ops.remove(0)));
                    }
                    inv.set_lst_parameters(ops);
                    inv.0
                }
                "N" | "KN" => {
                    let ops = self.rest();
                    let flags = p[2];
                    let n = if p.len() > 3 {
                        let n = NewExprent::new(VarType::new_signature(p[1]), Vec::new(), None);
                        let ctor = InvocationExprent::new();
                        let cls = n.get_new_type().value_or_null().to_string();
                        ctor.set_classname(cls);
                        ctor.set_name("<init>".to_string());
                        let desc = descriptor(p[3]);
                        ctor.set_string_descriptor(desc.clone());
                        ctor.set_descriptor(MethodDescriptor::parse_descriptor(&desc));
                        ctor.set_functype(InvocationKind::Init);
                        ctor.set_lst_parameters(ops);
                        n.set_constructor(Some(ctor));
                        n
                    } else if flags.contains('L') {
                        let n = NewExprent::new(VarType::new_signature(p[1]), Vec::new(), None);
                        n.set_lst_array_elements(ops);
                        n
                    } else {
                        NewExprent::new(VarType::new_signature(p[1]), ops, None)
                    };
                    n.set_var_arg_param(flags.contains('v'));
                    n.set_direct_array_init(flags.contains('d'));
                    if p[0] == "N" {
                        return n.0;
                    }
                    let k = KNewExprent::new(n);
                    if flags.contains('a') {
                        k.set_in_annotation(true);
                    }
                    if flags.contains('E') {
                        k.set_enum_const(true);
                    }
                    k.into()
                }
                "A" | "KA" => {
                    let ops = self.rest();
                    let c = if p[0] == "A" { 1 } else { 2 };
                    let names: Vec<String> = if p[c + 1] == "-" {
                        Vec::new()
                    } else {
                        p[c + 1].split(',').map(str::to_string).collect()
                    };
                    let a = AnnotationExprent::new(p[c].to_string(), names, ops);
                    if p[0] == "A" {
                        return a.0;
                    }
                    KAnnotationExprent::new_target(a, use_site_target(p[1])).into()
                }
                "KX" => {
                    let ops = self.rest();
                    let ret = match p[2] {
                        "-" => None,
                        "U" => Some(KType::UNIT().0),
                        sig => Some(VarType::new_signature(sig)),
                    };
                    let exit_type = if p[1] == "RETURN" {
                        ExitType::Return
                    } else {
                        ExitType::Throw
                    };
                    let e = ExitExprent::new(exit_type, ops.first().copied(), ret, None, None);
                    let k = KExitExprent::new(e);
                    if p[3] != "-" {
                        k.set_lambda_name(Some(p[3].to_string()));
                    }
                    k.into()
                }
                "KSH" => {
                    let ops = self.rest();
                    KSwitchHeadExprent::new(SwitchHeadExprent::new(ops[0], None)).into()
                }
                other => panic!("unknown head {other}"),
            };
        }
        if let Some(rest) = t.strip_prefix('G') {
            let bool_permitted = rest.starts_with('1');
            return ConstExprent::new_int(rest[2..].parse().unwrap(), bool_permitted, None).0;
        }
        if let Some(sig) = t.strip_prefix("T:").or_else(|| t.strip_prefix("CN:")) {
            return ConstExprent::new(VarType::new_signature(sig), None, None).0;
        }
        if let Some(sig) = t.strip_prefix("CL:") {
            return ConstExprent::new(
                VarType::VARTYPE_CLASS(),
                Some(ConstValue::String(sig.to_string())),
                None,
            )
            .0;
        }
        if t.starts_with("U:") {
            let p: Vec<&str> = t.split(':').collect();
            let spec = format!("{}:{}", p[2], p[3]);
            return ConstExprent::new(k_type(p[1]).0, value(&spec), None).0;
        }
        if t.starts_with("V:") {
            let p: Vec<&str> = t.split(':').collect();
            return VarExprent::new(p[1].parse().unwrap(), Some(vartype(p[2])), None).0;
        }
        if t.starts_with("FS:") || t.starts_with("FX:") {
            let p: Vec<&str> = t.split(':').collect();
            let class = if t.starts_with("FS:") {
                "b02/B02Fields"
            } else {
                p[1]
            };
            let (name, desc) = (p[p.len() - 2], p[p.len() - 1]);
            return FieldExprent::new(
                name.to_string(),
                class.to_string(),
                true,
                None,
                FieldDescriptor::parse_descriptor(desc),
                None,
            )
            .0;
        }
        let colon = 2 + t[2..].find(':').expect("C:TYPE:value");
        ConstExprent::new(vartype(&t[2..colon]), value(&t[colon + 1..]), None).0
    }
}

fn preorder(e: Exprent, out: &mut Vec<Exprent>) {
    out.push(e);
    for c in e.get_all_exprents() {
        preorder(c, out);
    }
}

fn index_of(all: &[Exprent], e: Exprent) -> i32 {
    all.iter().position(|&x| x == e).map_or(-1, |i| i as i32)
}

fn bounds(root: Exprent) -> String {
    let mut all = Vec::new();
    preorder(root, &mut all);
    let mut entries = Vec::new();
    for (i, &e) in all.iter().enumerate() {
        if !e.is_function() {
            continue;
        }
        let one = run(|| {
            let r = e.check_expr_type_bounds().expect("a result");
            let mut b = String::new();
            for p in r.get_lower_bounds() {
                b.push_str(&format!("L{}={},", index_of(&all, p.exprent), p.type_));
            }
            for p in r.get_upper_bounds() {
                b.push_str(&format!("U{}={},", index_of(&all, p.exprent), p.type_));
            }
            esc(Some(&b))
        });
        entries.push(format!("{i}:{one}"));
    }
    entries.join(" | ")
}

/// `getClass().getSimpleName()`.
fn class_name(e: Exprent) -> String {
    let base = match e.get_type() {
        ExprentType::Annotation => "AnnotationExprent",
        ExprentType::Array => "ArrayExprent",
        ExprentType::Assert => "AssertExprent",
        ExprentType::Assignment => "AssignmentExprent",
        ExprentType::Const => "ConstExprent",
        ExprentType::Exit => "ExitExprent",
        ExprentType::Field => "FieldExprent",
        ExprentType::Function => "FunctionExprent",
        ExprentType::If => "IfExprent",
        ExprentType::Invocation => "InvocationExprent",
        ExprentType::Monitor => "MonitorExprent",
        ExprentType::New => "NewExprent",
        ExprentType::Pattern => "PatternExprent",
        ExprentType::Switch => "SwitchExprent",
        ExprentType::SwitchHead => "SwitchHeadExprent",
        ExprentType::Var => "VarExprent",
        ExprentType::Yield => "YieldExprent",
        ExprentType::Other => "Exprent",
    };
    if e.is_kotlin() {
        format!("K{base}")
    } else {
        base.to_string()
    }
}

fn desc(root: Exprent) -> String {
    let mut all = Vec::new();
    preorder(root, &mut all);
    let mut parts = Vec::new();
    for e in all {
        let mut s = class_name(e);
        if let Some(f) = e.try_as_function() {
            s.push(':');
            s.push_str(f.get_func_type().name());
            if let Some(k) = e.try_as_k_function() {
                s.push('/');
                s.push_str(k.kd(|d| d.k_type).name());
            }
        }
        s.push_str(&format!("#{}", e.get_id()));
        parts.push(s);
    }
    parts.join(" ")
}

fn counter() -> i32 {
    DecompilerContext::get_counter_container().get_counter(CounterContainer::EXPRESSION_COUNTER)
}

/// Drops the attributes [`attributes`] puts into the per-thread side table.
struct ClearKtAttrs;

impl Drop for ClearKtAttrs {
    fn drop(&mut self) {
        KtAttrs::clear();
    }
}

/// `GenKt5Oracle.attributes()`.
fn attributes(guard: &common::ContextGuard) -> ClearKtAttrs {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/kt5/classes");
    guard.struct_context().add_space_file(&dir, true);
    let cl = guard
        .struct_context()
        .get_class("kt5/KtProps")
        .expect("kt5/KtProps");
    let property = |method: &str, desc: &str, name: &str, accessor: Option<PropertyMethod>| {
        let mt = cl.get_method(method, desc).expect("KtProps method");
        let element = KProperty::new(
            name.to_string(),
            None,
            0,
            None,
            None,
            None,
            None,
            None,
            None,
            cl,
        );
        KtAttrs::put(mt, &KElement::KEY(), KElement::Property(Rc::new(element)));
        if let Some(accessor) = accessor {
            KtAttrs::put(mt, &PropertyMethod::KEY(), accessor);
        }
    };
    property("getValue", "()I", "value", Some(PropertyMethod::Getter));
    property("setValue", "(I)V", "value", Some(PropertyMethod::Setter));
    property("getTop", "()I", "top", Some(PropertyMethod::Getter));
    property("getBroken", "()I", "broken", None);
    let function = |method: &str, desc: &str, flags: i32, receiver: Option<KType>| {
        let mt = cl.get_method(method, desc).expect("KtProps method");
        let element = KFunction::new(
            method.to_string(),
            Rc::from(Vec::<KParameter>::new()),
            Vec::new(),
            KType::UNIT(),
            flags,
            Vec::new(),
            Rc::new(|_| None),
            receiver,
            None,
            false,
            Rc::new(|_| -> DefaultArgsMap { jthrow!("no default arguments") }),
            Some(cl),
            Some(mt),
        );
        KtAttrs::put(mt, &KElement::KEY(), KElement::Function(Rc::new(element)));
    };
    let infix = Flags::IS_INFIX.to_flags(true);
    function("to", "(Ljava/lang/Object;)Ljava/lang/Object;", infix, None);
    function(
        "until",
        "(II)Ljava/lang/Object;",
        infix,
        Some(KType::UNIT()),
    );
    function("plain", "(Ljava/lang/Object;)Ljava/lang/Object;", 0, None);
    function("lonely", "()Ljava/lang/Object;", infix, None);
    ClearKtAttrs
}

struct Fixture {
    node: ClassNode,
    cl: StructClass,
    mt: StructMethod,
}

impl Fixture {
    fn fresh(&self) {
        DecompilerContext::start_class(ImportCollector::new(self.node));
        DecompilerContext::set_current_method_wrapper(None);
    }

    fn var_processor(&self) -> VarProcessor {
        let md = MethodDescriptor::parse_descriptor_struct(self.mt, None);
        VarProcessor::new(self.mt, &md)
    }

    fn method_wrapper(&self) -> MethodWrapper {
        MethodWrapper::new(
            None,
            self.var_processor(),
            self.mt,
            self.cl,
            CounterContainer::new(),
        )
    }

    fn tree(&self, mw: bool, tree: &str) -> Vec<String> {
        self.fresh();
        let mut built = None;
        let failed = run(|| {
            built = Some(Parser::build(tree));
            String::new()
        });
        let Some(e) = built else {
            return vec![failed];
        };
        let ids = counter().to_string();
        let expr_type = run(|| {
            esc(Some(
                &e.get_expr_type_opt()
                    .map_or("null".to_string(), |t| t.to_string()),
            ))
        });
        let bnds = run(|| esc(Some(&bounds(e))));
        self.fresh();
        let prec = run(|| e.get_precedence().to_string());
        self.fresh();
        if mw {
            DecompilerContext::set_current_method_wrapper(Some(self.method_wrapper()));
        }
        let mut buf: Option<TextBuffer> = None;
        let text = run(|| {
            let b = e.to_java(0);
            let s = b.convert_to_string_and_allow_data_discard();
            buf = Some(b);
            esc(Some(&s))
        });
        let reformatted = match buf {
            None => text.clone(),
            Some(mut b) => run(move || {
                b.reformat();
                esc(Some(&b.convert_to_string_and_allow_data_discard()))
            }),
        };
        let after = run(|| esc(Some(&desc(e))));

        self.fresh();
        let e2 = Parser::build(tree);
        let before = counter();
        let mut copy = None;
        let copy_ids = run(|| {
            copy = Some(e2.copy());
            (counter() - before).to_string()
        });
        let copy_desc = match copy {
            None => copy_ids.clone(),
            Some(c) => run(|| esc(Some(&desc(c)))),
        };
        if mw {
            DecompilerContext::set_current_method_wrapper(Some(self.method_wrapper()));
        }
        let copy_text = match copy {
            None => copy_ids.clone(),
            Some(c) => run(|| {
                esc(Some(
                    &c.to_java(0).convert_to_string_and_allow_data_discard(),
                ))
            }),
        };

        vec![
            ids,
            expr_type,
            bnds,
            prec,
            text,
            reformatted,
            after,
            copy_ids,
            copy_desc,
            copy_text,
        ]
    }

    fn pass(&self, which: &str, spec: &str) -> Vec<String> {
        self.fresh();
        DecompilerContext::set_property(
            "kt-collapse-string-concat",
            if which == "COLLAPSE0" { "0" } else { "1" },
        );
        let mut blocks: Vec<Statement> = Vec::new();
        let mut failed = None;
        for group in spec.split(" | ") {
            let bb = BasicBlockStatement::create().0;
            for tree in group.split(" ; ") {
                let r = run(|| {
                    let e = Parser::build(tree);
                    bb.get_exprents().expect("exprents").add(e);
                    String::new()
                });
                if !r.is_empty() {
                    failed = Some(r);
                }
            }
            blocks.push(bb);
        }
        if let Some(failed) = failed {
            return vec![failed];
        }
        let head = if blocks.len() == 1 {
            blocks[0]
        } else {
            SequenceStatement::new(blocks.clone()).0
        };
        let root = RootStatement::new(head, DummyExitStatement::new(), self.mt);
        let mut ctx = PassContext::new(
            Some(root),
            None,
            self.mt,
            self.cl,
            self.var_processor(),
            DecompileRecord::new(self.mt),
        );
        let res = run(|| {
            if which == "RESUGAR" {
                ResugarKotlinMethodsPass.run(&mut ctx)
            } else {
                CollapseStringConcatPass.run(&mut ctx)
            }
            .to_string()
        });
        let mut descs = Vec::new();
        let mut texts = Vec::new();
        for b in &blocks {
            for e in b.get_exprents().expect("exprents").iter() {
                descs.push(run(|| esc(Some(&desc(e)))));
                texts.push(run(|| {
                    esc(Some(
                        &e.to_java(0).convert_to_string_and_allow_data_discard(),
                    ))
                }));
            }
        }
        DecompilerContext::set_property("kt-collapse-string-concat", "1");
        vec![res, descs.join(" ; "), texts.join(" ; ")]
    }

    fn jmp(&self, name: &str) -> String {
        self.fresh();
        let stat = BasicBlockStatement::create().0;
        let target = BasicBlockStatement::create().0;
        let plain = BasicBlockStatement::create().0;
        SequenceStatement::new(vec![
            BasicBlockStatement::create().0,
            BasicBlockStatement::create().0,
        ]);
        let run_stat = SequenceStatement::new_empty().0;
        run_stat.set_kt(true);
        let is_switch = name.contains("switch");
        let closure = if name.contains("run") {
            Some(run_stat)
        } else if name.contains("noclosure") {
            None
        } else {
            Some(plain)
        };
        let type_ = if name.starts_with("continue") {
            StatEdge::TYPE_CONTINUE
        } else if name.starts_with("regular") {
            StatEdge::TYPE_REGULAR
        } else if name.starts_with("exception") {
            StatEdge::TYPE_EXCEPTION
        } else {
            StatEdge::TYPE_BREAK
        };
        let dest = if name.contains("exit") {
            DummyExitStatement::new().0
        } else {
            target
        };
        let e = StatEdge::new_closure(type_, stat, dest, closure);
        stat.add_successor(e);
        e.with_mut(|d| {
            d.labeled = name.contains("labeled");
            d.explicit = !name.contains("implicit");
        });
        if name.contains("two") {
            let two = StatEdge::new_closure(StatEdge::TYPE_BREAK, stat, target, Some(plain));
            stat.add_successor(two);
        }
        run(|| {
            esc(Some(
                &KExprProcessor::jmp_wrapper(stat, 1, is_switch)
                    .convert_to_string_and_allow_data_discard(),
            ))
        })
    }
}

/// The message of the first `unported!` among `columns`, if any.
fn unported(columns: &[String]) -> Option<String> {
    columns.iter().find_map(|c| {
        c.find("EXC:UnportedError:")
            .map(|i| c[i + 18..].to_string())
    })
}

struct Rows {
    checked: usize,
    failures: Vec<String>,
}

impl Rows {
    fn compare(&mut self, what: &str, names: &[&str], java: &[&str], rust: &[String]) {
        if let Some(message) = unported(rust) {
            panic!("{what}: reached unported {message}");
        }
        if java.len() != rust.len() {
            self.checked += 1;
            self.failures.push(format!(
                "{what} [shape]\n   java: {}\n   rust: {}",
                java.join(" || "),
                rust.join(" || ")
            ));
            return;
        }
        for (i, (j, r)) in java.iter().zip(rust.iter()).enumerate() {
            self.checked += 1;
            let agree = if names.get(i) == Some(&"bounds") && java.len() > 1 {
                same_bounds(j, r)
            } else {
                same(j, r)
            };
            if !agree {
                let name = if java.len() == 1 { "build" } else { names[i] };
                self.failures
                    .push(format!("{what} [{name}]\n   java: {j}\n   rust: {r}"));
            }
        }
    }
}

/// Bounds columns entry by entry ("i:pairs" joined by " | "), so that a
/// throw inside one entry compares like a column.
fn same_bounds(java: &str, rust: &str) -> bool {
    if java.starts_with("EXC:") || rust.starts_with("EXC:") {
        return same(java, rust);
    }
    let (Some(java), Some(rust)) = (unesc(java), unesc(rust)) else {
        return false;
    };
    let java: Vec<&str> = java.split(" | ").collect();
    let rust: Vec<&str> = rust.split(" | ").collect();
    java.len() == rust.len()
        && java.iter().zip(rust.iter()).all(|(j, r)| {
            let (jn, jv) = j.split_once(':').unwrap_or((j, ""));
            let (rn, rv) = r.split_once(':').unwrap_or((r, ""));
            jn == rn && same(jv, rv)
        })
}

const TREE_COLUMNS: [&str; 10] = [
    "ids",
    "exprType",
    "bounds",
    "precedence",
    "toJava",
    "reformatted",
    "after",
    "copyIds",
    "copyDesc",
    "copyText",
];

#[test]
fn kotlin_exprents_match_vineflower() {
    let guard = common::install_context_with(&[
        (IFernflowerPreferences::PREFERRED_LINE_LENGTH, "40"),
        ("kt-collapse-string-concat", "1"),
    ]);
    let _attributes = attributes(&guard);
    let path = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/b02/b02/B02Fields.class");
    let bytes = std::fs::read(path).expect("B02Fields.class");
    let cl = StructClass::create(&mut ByteCursor::new(bytes), true);
    let mt = cl.get_method("<init>", "()V").expect("B02Fields.<init>");
    let node = ClassNode::new(ClassNodeType::Root, cl);
    DecompilerContext::set_current_class_node(Some(node));
    DecompilerContext::set_current_class(Some(cl));
    let fixture = Fixture { node, cl, mt };

    let cases = CASES.lines().filter(|l| !l.starts_with('#')).count();
    let mut rows = Rows {
        checked: 0,
        failures: Vec::new(),
    };
    let mut seen = 0;
    for line in GOLDEN.lines() {
        seen += 1;
        let f: Vec<&str> = line.split('\t').collect();
        match f[0] {
            "T" => {
                let what: String = f[2].chars().take(160).collect();
                let rust = fixture.tree(f[1] == "1", f[2]);
                rows.compare(&what, &TREE_COLUMNS, &f[3..], &rust);
            }
            "P" => {
                let what = format!("{} {}", f[1], f[2].chars().take(160).collect::<String>());
                let rust = fixture.pass(f[1], f[2]);
                let java: Vec<String> = [f[3].to_string()]
                    .into_iter()
                    .chain(f[4..].iter().map(|c| unesc(c).expect("column")))
                    .collect();
                let java: Vec<&str> = java.iter().map(String::as_str).collect();
                rows.compare(&what, &["res", "descs", "texts"], &java, &rust);
            }
            "J" => {
                let rust = fixture.jmp(f[1]);
                let java = f.get(2).copied().unwrap_or("");
                rows.compare(f[1], &["text"], &[java], &[rust]);
            }
            other => panic!("unknown row {other}"),
        }
    }

    eprintln!("Kotlin exprent rows: {} columns checked", rows.checked);
    assert!(seen >= cases, "{seen} golden rows for {cases} cases");
    assert!(
        rows.checked >= 8979,
        "only {} columns checked",
        rows.checked
    );
    assert!(
        rows.failures.is_empty(),
        "{} mismatches:\n{}",
        rows.failures.len(),
        rows.failures
            .iter()
            .take(30)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}
